import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { deleteFollowUser } from "../handlers/deleteFollowUser";
import type { ApiError } from "../runtime/client";
import type { Partition } from "../types/Partition";
import type { SpacePartition } from "../types/SpacePartition";

type Data = Awaited<ReturnType<typeof deleteFollowUser>>;
type Vars = { spaceId: SpacePartition; userPk: Partition };

export function useDeleteFollowUser(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => deleteFollowUser(vars.spaceId, vars.userPk),
    ...options,
  });
}
